/* ------------------------------------------------------------------ projects (#214) */

export type StudioProjectCategory = "3D" | "Motion" | "Stills";

export type ProjectArt = "bloom" | "glass" | "monolith" | "orbit" | "ribbons" | "streaks" | "folds" | "loop" | "flats" | "harbor" | "desert" | "window";

export interface StudioProject {
  id: string;
  title: string;
  category: StudioProjectCategory;
  client: string;
  year: number;
  tools: string[];
  description: string;
  /** Generated still, 1200×750 (16:10). */
  src: string;
  alt: string;
  /** Running time for Motion pieces, e.g. "0:42". */
  duration?: string;
  /** Generator recipe. */
  art: ProjectArt;
  /** Backdrop first, then accents. */
  colors: string[];
  seed: number;
}

type ProjectSpec = [id: string, title: string, category: StudioProjectCategory, client: string, year: number, tools: string[], description: string, art: ProjectArt, colors: string[], alt: string, duration?: string];

